import json,numpy as np
from PIL import Image
D='/app/output/after_side_grasp_lift/';meta=json.load(open(D+'meta.json'));spec=json.load(open('/app/output/spec.json'))
for cam in ['ego','wrist_right']:
 rgb=np.array(Image.open(D+cam+'.png'));dep=np.load(D+cam+'_depth.npy');Y,X=np.mgrid[:480,:848]
 if cam=='ego': region=(X>500)&(X<550)&(Y>340)&(Y<410)
 else: region=(X>410)&(X<510)&(Y>320)&(Y<390)
 m=(rgb[:,:,2]>rgb[:,:,0]*1.12)&(rgb[:,:,2]>rgb[:,:,1]*1.03)&(rgb[:,:,2]>80)&region
 yy,xx=np.where(m); print(cam,len(xx),(xx.min(),yy.min(),xx.max(),yy.max()) if len(xx) else None)
 E=np.array(meta['cameras'][cam]['extrinsic_cv']);K=np.array(spec['cameras'][cam]['intrinsic_cv']);T=np.eye(4);T[:3]=E;C=np.linalg.inv(T);pts=[]
 for u,v in zip(xx,yy):
  z=float(dep[v,u]);
  if z<=0:continue
  p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);pts.append(C@p)
 if pts:
  p=np.array(pts);print('dep med',np.median(dep[yy,xx]),'xyz med',np.median(p[:,:3],axis=0),'q10/90',np.quantile(p[:,:3],[.1,.9],axis=0))
print('tcp',meta['proprio']['now'][16:23])
